import { useEffect, useState } from "react";
import API from "../services/api";
import "./Favoritos.css";

function Favoritos (){

 const [favoritos,setFavoritos] = useState([]);
 const [filtro,setFiltro] = useState("");

 const usuario = JSON.parse(localStorage.getItem("usuario"));

 useEffect(()=>{
  cargarFavoritos();
 },[]);


 const cargarFavoritos = async ()=>{

  try{

   const res = await API.get(`/favoritos/${usuario.id_usuario}`);

   setFavoritos(res.data);

  }catch(error){

   console.log(error);

  }

 };


 // ======================
 // FILTRO
 // ======================

 const filtrados = favoritos.filter(p =>
  p.tipo_producto.toLowerCase().includes(filtro.toLowerCase()) ||
  p.color.toLowerCase().includes(filtro.toLowerCase()) ||
  p.peso.toString().includes(filtro)
 );


 // ======================
 // ELIMINAR FAVORITO
 // ======================

 const eliminarFavorito = async (id_producto)=>{

  try{

   await API.delete(`/favoritos/${usuario.id_usuario}/${id_producto}`);

   cargarFavoritos();

  }catch(error){

   console.log(error);

  }

 };


 // ======================
 // COMPRAR
 // ======================

 const comprar = async (id_producto)=>{

  try{

   await API.post("/comprar",{
    id_usuario: usuario.id_usuario,
    id_producto
   });

   alert("Compra realizada");

   cargarFavoritos();

  }catch(error){

   console.log(error);

  }

 };


 return(

  <div className="favoritos-container">

   <h2>Mis Favoritos</h2>

   <input
    type="text"
    placeholder="Buscar por color, peso o nombre..."
    value={filtro}
    onChange={(e)=>setFiltro(e.target.value)}
    className="input-busqueda"
   />


   <div className="grid">

    {filtrados.map((p)=>{

     const noDisponible = p.estado === "vendido";

     return(

      <div className="card" key={p.id_producto}>

       <img
        src={`http://localhost:3000/uploads/${p.imagen}`}
        alt=""
       />

       <h3>{p.tipo_producto}</h3>

       <p>Color: {p.color}</p>
       <p>Peso: {p.peso} ct</p>

       <h2>${p.valor}</h2>


       {noDisponible && (
        <p className="no-disponible">No disponible</p>
       )}


       <button
        disabled={noDisponible}
        onClick={()=>comprar(p.id_producto)}
        className="btn-comprar"
       >
        {noDisponible ? "No disponible" : "Comprar"}
       </button>


       <button
        onClick={()=>eliminarFavorito(p.id_producto)}
        className="btn-eliminar"
       >
        ❌ Quitar
       </button>

      </div>

     );

    })}

   </div>

  </div>

 );

}

export default MisFavoritos;
